#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;

    const string suits = "CEUP";
    bool seen[4][14] = {};
    bool duplicate[4] = {};

    for (size_t i = 0; i < s.size(); i += 3) {
        int value = stoi(s.substr(i, 2));
        int suit = suits.find(s[i + 2]);

        if (seen[suit][value]) {
            duplicate[suit] = true;
        }
        seen[suit][value] = true;
    }

    for (int suit = 0; suit < 4; ++suit) {
        if (duplicate[suit]) {
            cout << "erro\n";
        } else {
            int missing = 0;
            for (int value = 1; value <= 13; ++value) {
                if (!seen[suit][value]) ++missing;
            }
            cout << missing << '\n';
        }
    }

    return 0;
}
